// Producer 端：开启幂等 + 事务
Properties pp = new Properties();
pp.put("acks", "all");
pp.put("enable.idempotence", "true");
pp.put("transactional.id", "order-pipeline-tx-1"); // 必须稳定且唯一
KafkaProducer<String, String> producer = new KafkaProducer<>(pp);
producer.initTransactions(); // 注册 PID 并 fence 旧实例

// Consumer 端：关闭自动提交，配合事务读
Properties cp = new Properties();
cp.put("enable.auto.commit", "false");
cp.put("isolation.level", "read_committed"); // 只读已提交事务
KafkaConsumer<String, String> consumer = new KafkaConsumer<>(cp);
consumer.subscribe(List.of("orders"));

while (true) {
  ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(500));
  if (records.isEmpty()) continue;
  producer.beginTransaction();
  try {
    for (ConsumerRecord<String, String> r : records) {
      // 业务处理 + 写下游 topic
      producer.send(new ProducerRecord<>("orders.enriched", r.key(), enrich(r.value())));
    }
    // 把消费位移塞进同一个事务，原子提交
    Map<TopicPartition, OffsetAndMetadata> offsets = currentOffsets(records);
    producer.sendOffsetsToTransaction(offsets, consumer.groupMetadata());
    producer.commitTransaction();
  } catch (KafkaException e) {
    producer.abortTransaction(); // 下次 poll 会从未提交位移重读
  }
}
